<?php
require 'config.php';$cat=(int)($_GET['category']??0);$q=trim($_GET['q']??'');$sql='SELECT p.id,p.name,p.description,p.price,p.stock,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.active=1';$args=[];if($cat){$sql.=' AND p.category_id=?';$args[]=$cat;}if($q!==''){$sql.=' AND (p.name LIKE ? OR p.description LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}$sql.=' ORDER BY p.name';$st=$pdo->prepare($sql);$st->execute($args);$items=$st->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Products · Mahavir Store</title><link rel="stylesheet" href="assets/css/store-theme.css"></head><body><header class="store-header"><a class="store-logo" href="index.php">🛒 Mahavir Provision Store</a><a href="cart.php">Cart</a></header><main class="store-container"><h1>Products</h1><div class="product-grid"><?php foreach($items as $p):?><article class="product-card"><div class="product-art">🛒</div><small><?=e($p['category']??'Grocery')?></small><h3><?=e($p['name'])?></h3><p class="muted"><?=e($p['description']??'')?></p><div class="product-bottom"><b>₹<?=number_format((float)$p['price'],2)?></b><button class="add-btn" onclick='addToCart(<?=$p['id']?>,<?=json_encode($p['name'])?>,<?=json_encode((float)$p['price'])?>)'>+</button></div></article><?php endforeach;?></div><?php if(!$items):?><p>No matching products found.</p><?php endif;?></main><script src="assets/js/app.js"></script></body></html>